(4249470, 612299, 83313, '<td valign="top">The slight tilt and perspective makes it seem a little dizzy, Like I just got up from napping under this tree. I love the colors, and composition.</td>', 'The slight tilt and perspective makes it seem a little dizzy, Like I just got up from napping under this tree. I love the colors, and composition.', '2007-11-15 13:45:31.000000', NULL, 1),
(4249488, 610948, 83313, '<td valign="top">Looks bold against the blue sky. Lower half of the image is a little busy and distracting from the rest of it, though.</td>', 'Looks bold against the blue sky. Lower half of the image is a little busy and distracting from the rest of it, though.', '2007-11-15 14:02:13.000000', NULL, 1),
(4249497, 610439, 83313, '<td valign="top">The reflections from the glass distract from the subject. Is that his head he is holding? sort of?</td>', 'The reflections from the glass distract from the subject. Is that his head he is holding? sort of?', '2007-11-15 14:07:14.000000', NULL, 1),
(4249507, 611530, 83313, '<td valign="top">Suggestive without being too upfront about it. Nice idea. Missing a lot of visual detail between the bright bulb and the dark negligee in shadows. Some addtional lighting for the front may have helped.</td>', 'Suggestive without being too upfront about it. Nice idea. Missing a lot of visual detail between the bright bulb and the dark negligee in shadows. Some addtional lighting for the front may have helped.', '2007-11-15 14:11:07.000000', NULL, 1),
(4249511, 610781, 83313, '<td valign="top">I like it. Nice contrast between the golden field and the blue sky. A bit of artifacting is visible in the sky on the left, just above the tree.</td>', 'I like it. Nice contrast between the golden field and the blue sky. A bit of artifacting is visible in the sky on the left, just above the tree.', '2007-11-15 14:12:59.000000', NULL, 1),
(4249514, 612913, 83313, '<td valign="top">A good view. I''m a sucker for shots with lots of texture.</td>', 'A good view. I''m a sucker for shots with lots of texture.', '2007-11-15 14:14:00.000000', NULL, 1),
