INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4249795, 611458, 59335, '<td valign="top">Oh boy.  lighting needs work- too harsh</td>', 'Oh boy.  lighting needs work- too harsh', '2007-11-15 16:05:29.000000', NULL, 1),
(4249808, 610884, 811, '<td valign="top">Great lighting on this.  Nice work.</td>', 'Great lighting on this.  Nice work.', '2007-11-15 16:10:33.000000', NULL, 1),
(4249811, 612727, 811, '<td valign="top">Simple in composition, but nice.  I like the simple colors, as well.</td>', 'Simple in composition, but nice.  I like the simple colors, as well.', '2007-11-15 16:10:50.000000', NULL, 1),
(4249812, 613093, 811, '<td valign="top">good details on the bubbles.  also a nice contrast level.</td>', 'good details on the bubbles.  also a nice contrast level.', '2007-11-15 16:11:07.000000', NULL, 1),
(4249813, 612851, 811, '<td valign="top">good even lighting.  i, personally, am not crazy about using little statues, etc. as subjects.  however, i do recognize that they can be valuable in learning how to setting light, etc.</td>', 'good even lighting.  i, personally, am not crazy about using little statues, etc. as subjects.  however, i do recognize that they can be valuable in learning how to setting light, etc.', '2007-11-15 16:11:56.000000', NULL, 1),
(4249815, 610685, 811, '<td valign="top">good composition and use of dof.  took me a minute to see what was topless. . .</td>', 'good composition and use of dof.  took me a minute to see what was topless. . .', '2007-11-15 16:12:28.000000', NULL, 1),
(4249820, 612446, 78527, '<td valign="top">just too dark</td>', 'just too dark', '2007-11-15 16:13:18.000000', NULL, 1),
(4249822, 611438, 811, '<td valign="top">nice colors.  exposure seems a bit uneven</td>', 'nice colors.  exposure seems a bit uneven', '2007-11-15 16:13:44.000000', NULL, 1),
(4249824, 610848, 811, '<td valign="top">great colors, details and exposure.  nice shot.  i wouldn''t immediately think "topless" but stretching can be good.</td>', 'great colors, details and exposure.  nice shot.  i wouldn''t immediately think "topless" but stretching can be good.', '2007-11-15 16:14:27.000000', NULL, 1),
(4249827, 612975, 811, '<td valign="top">did you use a flash?  if so, i think you were a bit too close because it is reflecting strongly.  also, it appears as if you were to close to focus clearly.  this looks like it would be a really interesting and humorous shot, but the technicality lackings really detract from the overall effect.</td>', 'did you use a flash?  if so, i think you were a bit too close because it is reflecting strongly.  also, it appears as if you were to close to focus clearly.  this looks like it would be a really interesting and humorous shot, but the technicality lackings really detract from the overall effect.', '2007-11-15 16:15:35.000000', NULL, 1),
(4249832, 612622, 811, '<td valign="top">great composition and i like how the match almost has a personality. :)  doesn''t scream "topless" to me, but i can see where you are coming from -- hope others can as well.</td>', 'great composition and i like how the match almost has a personality. :)  doesn''t scream "topless" to me, but i can see where you are coming from -- hope others can as well.', '2007-11-15 16:16:20.000000', NULL, 1),
(4249835, 612981, 811, '<td valign="top">I like the strong color contrast in this</td>', 'I like the strong color contrast in this', '2007-11-15 16:17:08.000000', NULL, 1),
(4249836, 612981, 45631, '<td valign="top">Great minds think alike - just so hard to be unique these days, lol. The red, green and white are striking but the focus is rather soft (this may have been your intention though). Well done.</td>', 'Great minds think alike - just so hard to be unique these days, lol. The red, green and white are striking but the focus is rather soft (this may have been your intention though). Well done.', '2007-11-15 16:17:19.000000', NULL, 1),
(4249838, 612916, 811, '<td valign="top">i like the complexity of the structure and how it contrasts with the simplicity of the colors.</td>', 'i like the complexity of the structure and how it contrasts with the simplicity of the colors.', '2007-11-15 16:17:42.000000', NULL, 1),
(4249850, 612903, 811, '<td valign="top">You are onto a good idea here, i think.  using what you have i would make a couple of suggestions.  first, get a lower perspective.  this perspective makes the bottle feel small, and i feel as if i am simply standing and looking down on it.  a lower perspective would help the bottle to fill the frame more and give it more "importance" or at least a feeling of more importance.  Secondly, the lighting feels a bit off.  It almost feels like a flash was used, but you are missing the shadows (which is a good thing).  Covering your lights with a soft cloth may help you to diffuse them more.  Also, this gives the feeling of being dramatic (not quite romantic) so don''t  perhaps a darker shot would be more effective.  Lose the coaster, it looks completely out of place.  The woodgrain of the surface gives it a casual look.  Putting down a piece of fabric would give it  a more uniform look, and would solve the problem of needing a coaster.  Also, you could choose whatever color you want.  The are of the shot isn''t large, so you could even use a t-shirt or something.   Again, you''ve got a good idea, and the topless theme is repeated throughout the shot, which is good, but the execution of the shot makes it leave a bit to be desire.</td>', 'You are onto a good idea here, i think.  using what you have i would make a couple of suggestions.  first, get a lower perspective.  this perspective makes the bottle feel small, and i feel as if i am simply standing and looking down on it.  a lower perspective would help the bottle to fill the frame more and give it more "importance" or at least a feeling of more importance.  Secondly, the lighting feels a bit off.  It almost feels like a flash was used, but you are missing the shadows (which is a good thing).  Covering your lights with a soft cloth may help you to diffuse them more.  Also, this gives the feeling of being dramatic (not quite romantic) so don''t  perhaps a darker shot would be more effective.  Lose the coaster, it looks completely out of place.  The woodgrain of the surface gives it a casual look.  Putting down a piece of fabric would give it  a more uniform look, and would solve the problem of needing a coaster.  Also, you could choose whatever color you want.  The are of the shot isn''t large, so you could even use a t-shirt or something.   Again, you''ve got a good idea, and the topless theme is repeated throughout the shot, which is good, but the execution of the shot makes it leave a bit to be desire.', '2007-11-15 16:24:18.000000', NULL, 1),
(4249863, 610886, 811, '<td valign="top">The composition is too centered, I think and the circular motion of the mat is a bit distracting.  However, I think a closer crop of this would be much more effective because it looks like the details are really good.</td>', 'The composition is too centered, I think and the circular motion of the mat is a bit distracting.  However, I think a closer crop of this would be much more effective because it looks like the details are really good.', '2007-11-15 16:27:31.000000', NULL, 1),
