(4254141, 612573, 83313, '<td valign="top">Nice colors and concept, and there are no people in it, even though it is implied. Very creative.</td>', 'Nice colors and concept, and there are no people in it, even though it is implied. Very creative.', '2007-11-17 14:00:22.000000', NULL, 1),
(4254145, 612955, 83313, '<td valign="top">Nice, but the colors seem a little dull for this subject. This could have popped of of the screen, with that bold red and reflections.</td>', 'Nice, but the colors seem a little dull for this subject. This could have popped of of the screen, with that bold red and reflections.', '2007-11-17 14:03:36.000000', NULL, 1),
(4254149, 612342, 83313, '<td valign="top">I like the look of bottle in the foreground. I find my eye drawn to the out of focus one in the middle, though.</td>', 'I like the look of bottle in the foreground. I find my eye drawn to the out of focus one in the middle, though.', '2007-11-17 14:05:12.000000', NULL, 1),
(4254152, 610719, 83313, '<td valign="top">I love interesting old buildings. Nice. Got some other shots from this session?</td>', 'I love interesting old buildings. Nice. Got some other shots from this session?', '2007-11-17 14:06:32.000000', NULL, 1),
(4254155, 612490, 83313, '<td valign="top">The blue tablecloth draws my eye away from the main subject.</td>', 'The blue tablecloth draws my eye away from the main subject.', '2007-11-17 14:07:09.000000', NULL, 1),
(4254157, 613088, 83313, '<td valign="top">Well, there are not any topless people visible! I like the implication, though. Nice street shot. I like the way the lighting works.</td>', 'Well, there are not any topless people visible! I like the implication, though. Nice street shot. I like the way the lighting works.', '2007-11-17 14:09:27.000000', NULL, 1),
(4254160, 610884, 83313, '<td valign="top">Unfortunately, I find no interest in this, it seems kind of plain to me. But, it''s a good effort at a different perspective.</td>', 'Unfortunately, I find no interest in this, it seems kind of plain to me. But, it''s a good effort at a different perspective.', '2007-11-17 14:11:34.000000', NULL, 1),
(4254163, 612467, 83313, '<td valign="top">Nice composition, color, and lighting. A shame the fruit itself is slightly out of focus, though.</td>', 'Nice composition, color, and lighting. A shame the fruit itself is slightly out of focus, though.', '2007-11-17 14:12:40.000000', NULL, 1),
(4254164, 611034, 83313, '<td valign="top">This looks washed out from a flash used at close range.</td>', 'This looks washed out from a flash used at close range.', '2007-11-17 14:13:26.000000', NULL, 1),
(4254170, 612415, 83313, '<td valign="top">I like most of this shot. I seem to take a lot of similar ones, myself. The composition may be just a little too centered. I''m not sure. I wouldn''t mind seeing some other shots from this session</td>', 'I like most of this shot. I seem to take a lot of similar ones, myself. The composition may be just a little too centered. I''m not sure. I wouldn''t mind seeing some other shots from this session', '2007-11-17 14:16:01.000000', NULL, 1),
