(4254291, 612340, 78483, '<td valign="top">I like the Composition</td>', 'I like the Composition', '2007-11-17 16:08:36.000000', NULL, 1),
(4254295, 612850, 67258, '<td valign="top">Differential equations - in fact maths in general - was never my strong point, and I am really struggling to understand the photograph in terms of both its title and the challenge.  That said, as an image I do like it - the composition is cool, with its diagonal leading line running from bottom left to top right combined with the dimishing perspective.</td>', 'Differential equations - in fact maths in general - was never my strong point, and I am really struggling to understand the photograph in terms of both its title and the challenge.  That said, as an image I do like it - the composition is cool, with its diagonal leading line running from bottom left to top right combined with the dimishing perspective.', '2007-11-17 16:18:35.000000', NULL, 1),
(4254446, 612299, 77507, '<td valign="top">surprisingingly nice control of color without appearing oversaturated.  Nice job.  Great to see the use of contrast too with the shadows.<br/>Not sure where the topless comes in--unless it refers to the photographer?</td>', 'surprisingingly nice control of color without appearing oversaturated.  Nice job.  Great to see the use of contrast too with the shadows.Not sure where the topless comes in--unless it refers to the photographer?', '2007-11-17 18:40:59.000000', NULL, 1),
(4254447, 613079, 77507, '<td valign="top">Very nice composition<br/>Is it a little underexposed &amp; cold color temp?</td>', 'Very nice compositionIs it a little underexposed & cold color temp?', '2007-11-17 18:41:50.000000', NULL, 1),
(4254449, 612446, 77507, '<td valign="top">Nice composition.<br/>Perhaps watch your levels (seems to need more white clip) &amp; exposure</td>', 'Nice composition.Perhaps watch your levels (seems to need more white clip) & exposure', '2007-11-17 18:43:37.000000', NULL, 1),
