INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4254967, 613018, 15360, '<td valign="top">I think you might enjoy the Nude Photography expo currently at the Getty Center.  There are a few photographs in the nude gallery that feature fruits and vegetables representing human genitalia.  While I think your photograph is humorous it lacks the imagery I have seen in other similar photographs.  Good fun idea, a different composition in my opinion would result in added points.</td>', 'I think you might enjoy the Nude Photography expo currently at the Getty Center.  There are a few photographs in the nude gallery that feature fruits and vegetables representing human genitalia.  While I think your photograph is humorous it lacks the imagery I have seen in other similar photographs.  Good fun idea, a different composition in my opinion would result in added points.', '2007-11-18 01:20:39.000000', NULL, 1),
(4254968, 611663, 15360, '<td valign="top">One of my favorites of this challenge, good luck!</td>', 'One of my favorites of this challenge, good luck!', '2007-11-18 01:23:43.000000', NULL, 1),
